// Extract search params from webhook
const body = $input.first().json.body || $input.first().json;
const segments = body.segments || [];
const states = body.states || [];
const city = body.city || '';
const keywords = body.keywords || [];
const revenueMin = parseInt(body.revenueMin) || 70000;
const revenueMax = parseInt(body.revenueMax) || 2000000;

// Build Google Maps queries — one per segment for better results
const stateNames = { AC: 'Acre', AL: 'Alagoas', AP: 'Amapá', AM: 'Amazonas', BA: 'Bahia', CE: 'Ceará', DF: 'Distrito Federal', ES: 'Espírito Santo', GO: 'Goiás', MA: 'Maranhão', MT: 'Mato Grosso', MS: 'Mato Grosso do Sul', MG: 'Minas Gerais', PA: 'Pará', PB: 'Paraíba', PR: 'Paraná', PE: 'Pernambuco', PI: 'Piauí', RJ: 'Rio de Janeiro', RN: 'Rio Grande do Norte', RS: 'Rio Grande do Sul', RO: 'Rondônia', RR: 'Roraima', SC: 'Santa Catarina', SP: 'São Paulo', SE: 'Sergipe', TO: 'Tocantins' };

// Build search queries: use first segment + keywords (not all segments joined)
const primarySegment = segments[0] || '';
const searchTerms = [primarySegment, ...keywords].filter(Boolean);
const query = searchTerms.join(' ') || 'empresas';

// Build location: use all selected states for broader coverage
const stateNamesList = states.map(s => stateNames[s] || s).filter(Boolean);
const location = city
  ? `${city}, ${stateNamesList[0] || 'Brasil'}`
  : stateNamesList.length > 0
    ? stateNamesList[0]
    : 'Brasil';

// Build additional search strings for multi-segment queries
const searchStrings = segments.length > 1
  ? segments.slice(0, 3).map(seg => [seg, ...keywords].filter(Boolean).join(' '))
  : [query];

return [{
  json: {
    query,
    searchStrings,
    location,
    segments,
    states,
    stateNamesList,
    city,
    keywords,
    revenueMin,
    revenueMax,
    searchId: Date.now().toString()
  }
}];

// Wait for Apify run to complete
const runId = $input.first().json.data.id;
const token = 'apify_api_IcL12FYoB2JQf0NdZ89DrAUvoUQVSA2xh8sf';
let status = 'RUNNING';
let datasetId = '';

while (status === 'RUNNING' || status === 'READY') {
  await new Promise(r => setTimeout(r, 5000));
  const resp = await fetch(`https://api.apify.com/v2/acts/compass~crawler-google-places/runs/${runId}?token=${token}`);
  const data = await resp.json();
  status = data.data.status;
  datasetId = data.data.defaultDatasetId;
}

if (status !== 'SUCCEEDED') throw new Error(`Apify run failed: ${status}`);

// Get results
const itemsResp = await fetch(`https://api.apify.com/v2/datasets/${datasetId}/items?token=${token}&limit=100`);
const items = await itemsResp.json();

return [{ json: { items, count: items.length, datasetId } }];

// Process Google Maps results: filter, score, enrich
const items = $input.first().json.items;
const params = $('Parse Params').first().json;
const revenueMin = params.revenueMin;
const revenueMax = params.revenueMax;
const MAX_LEADS = 15;

const leads = items
  .filter(item => item.title)
  .map((item, index) => {
    // Phone validation
    const rawPhone = item.phone || '';
    const digits = rawPhone.replace(/\D/g, '').replace(/^0+/, '');
    const fullPhone = digits.length >= 10 ? (digits.startsWith('55') ? digits : '55' + digits) : '';
    const isMobile = fullPhone.length >= 12 && fullPhone.charAt(4) === '9';

    // Revenue estimation (improved: also considers category and website)
    const reviews = item.reviewsCount || 0;
    let revenue = 70000;
    if (reviews >= 200) revenue = 500000;
    else if (reviews >= 100) revenue = 300000;
    else if (reviews >= 50) revenue = 200000;
    else if (reviews >= 30) revenue = 150000;
    else if (reviews >= 15) revenue = 100000;
    else if (reviews >= 5) revenue = 80000;
    if (item.website && !item.website.includes('instagram.com')) revenue = Math.round(revenue * 1.2);
    const cityLower = (item.city || params.city || '').toLowerCase();
    if (['são paulo', 'rio de janeiro', 'belo horizonte'].some(c => cityLower.includes(c))) revenue = Math.round(revenue * 1.3);

    // SPICED
    const hasWebsite = item.website && !item.website.includes('instagram.com');
    const hasIG = item.socialProfiles?.instagram;
    const rating = item.totalScore || 0;
    const presence = (hasWebsite ? 3 : 0) + (hasIG ? 2 : 0) + (rating >= 4 ? 1 : 0) + (reviews >= 30 ? 1 : 0);

    const spicedS = Math.min(1 + (hasWebsite ? 1 : 0) + (rating >= 4 ? 1 : 0) + (reviews >= 20 ? 1 : 0) + (presence >= 5 ? 1 : 0), 5);
    const spicedP = Math.max(5 - (hasWebsite ? 1 : 0) - (presence >= 5 ? 1 : 0) - (reviews >= 50 ? 1 : 0), 1);
    const spicedI = presence <= 2 ? 5 : presence <= 4 ? 4 : 3;
    const spicedC = presence <= 3 ? 4 : 3;
    const spicedD = Math.min(2 + (item.website || hasIG ? 1 : 0), 5);
    const score = Math.round((spicedS*0.25 + spicedP*0.25 + spicedI*0.20 + spicedC*0.15 + spicedD*0.15) * 10) / 10;
    const temperature = score >= 4 ? 'HOT' : score >= 3 ? 'WARM' : 'COLD';

    // Employees & years estimate
    const employees = revenue >= 120000 ? 8 : revenue >= 70000 ? 5 : 3;
    const yearsInMarket = revenue >= 120000 ? 7 : revenue >= 70000 ? 5 : 3;
    const tier = revenue >= 830000 ? 'Medium=' : revenue >= 200000 ? 'Medium-' : revenue >= 100000 ? 'Small' : 'Micro+';

    // Trap
    let trap = 'T1 - Aquisição de clientes';
    if (hasWebsite && presence <= 5) trap = 'T6 - Posicionamento de marca';
    else if (reviews < 15) trap = 'T2 - Conversão de vendas';

    return {
      companyName: item.title,
      segment: params.segments[0] || item.categoryName || '',
      tier,
      monthlyRevenue: revenue,
      employees,
      yearsInMarket,
      status: 'Novo',
      score,
      temperature,
      spicedS, spicedP, spicedI, spicedC, spicedD,
      hypotheticalTrap: trap,
      website: item.website || '',
      instagram: item.socialProfiles?.instagram || '',
      linkedin: item.socialProfiles?.linkedin || '',
      facebook: item.socialProfiles?.facebook || '',
      address: item.address || '',
      city: item.city || params.city || '',
      state: item.state || params.states[0] || '',
      businessSummary: `${item.categoryName || ''} · ${reviews} avaliações (${rating}★) · Presença digital: ${presence}/10`,
      enrichmentStatus: 'pending',
      whatsapp: isMobile ? fullPhone : '',
      phone: rawPhone,
      email: (item.emails || [])[0] || '',
      ownerName: item.title,
      isMobile,
      estimatedRevenue: revenue
    };
  })
  // FILTER: Revenue in range (wider tolerance — enrichment will refine later)
  .filter(lead => lead.estimatedRevenue >= revenueMin * 0.5 && lead.estimatedRevenue <= revenueMax * 1.5);

// SORT: Prioritize leads with WhatsApp, then by score (best first)
leads.sort((a, b) => {
  if (a.isMobile && !b.isMobile) return -1;
  if (!a.isMobile && b.isMobile) return 1;
  return b.score - a.score;
});

// LIMIT: Return up to MAX_LEADS (10-15 target)
const finalLeads = leads.slice(0, MAX_LEADS);

return finalLeads.map(lead => ({ json: lead }));
